// Ratchet & pawl, pure model. Design: vertical wheel shaft at origin (z up), all motion in XY planes.
// Stack (mm): base 0..8, wheel+pawls 10..18 (same plane = real contact), lever 21..27 on shaft collar,
// crank disc at O2 21..27 driven about z, coupler 29..33 joins crank pin and lever pin.
// Drive: crank-rocker four-bar -> lever swing > one tooth pitch; drive pawl on lever pushes radial faces (CCW only);
// holding pawl on a base post blocks CW. Idealized rigid kinematics, no forces/friction/load rating.
export const D = {
  N: 12, rT: 40, rR: 32, zW: [10, 18], zL: [21, 27], zC: [29, 33], zBase: [0, 8],
  R: 70, O2: [70, -75], r: 26, L: 75, pinR: 50, pinBack: 48 * Math.PI / 180, period: 3,
};
D.p = 2 * Math.PI / D.N;
const tau = 2 * Math.PI, mod = (a, m) => ((a % m) + m) % m;
export function leverAt(a) {
  const C = [D.O2[0] + D.r * Math.cos(a), D.O2[1] + D.r * Math.sin(a)];
  const d = Math.hypot(C[0], C[1]), x = (d * d + D.R * D.R - D.L * D.L) / (2 * d), h = Math.sqrt(Math.max(0, D.R * D.R - x * x));
  const ux = C[0] / d, uy = C[1] / d;
  const c1 = [ux * x - uy * h, uy * x + ux * h], c2 = [ux * x + uy * h, uy * x - ux * h];
  const B = c1[0] > c2[0] ? c1 : c2;
  return { C, B, phi: Math.atan2(B[1], B[0]) };
}
// locate extreme crank angles numerically
let aMin = 0, aMax = 0, fMin = 9, fMax = -9;
for (let i = 0; i < 7200; i++) { const a = i * tau / 7200, f = leverAt(a).phi; if (f < fMin) { fMin = f; aMin = a; } if (f > fMax) { fMax = f; aMax = a; } }
D.phiMin = fMin; D.phiMax = fMax; D.swing = fMax - fMin; D.delta = D.swing - D.p;
D.dir = mod(aMax - aMin, tau) < Math.PI ? 1 : -1; // crank sense that makes the working stroke the shorter? keep direction to aMax
D.tWork = (D.dir > 0 ? mod(aMax - aMin, tau) : mod(aMin - aMax, tau)) / tau;
export const crankAngle = (t) => aMin + D.dir * tau * t;
// pawl tip for radius rho: circle(0,rho) ∩ circle(pin,Lp), CCW branch
function tipFor(pin, Lp, rho) {
  const d = Math.hypot(pin[0], pin[1]), x = (rho * rho - Lp * Lp + d * d) / (2 * d), h = Math.sqrt(Math.max(0, rho * rho - x * x));
  const ux = pin[0] / d, uy = pin[1] / d;
  return [ux * x - uy * h, uy * x + ux * h];
}
const lv = [D.pinR, 0], tipR = [D.rR * Math.cos(D.pinBack), D.rR * Math.sin(D.pinBack)];
D.Lp = Math.hypot(tipR[0] - lv[0], tipR[1] - lv[1]);
const cD = D.pinBack;
D.eps = 0.004; // tip seats a hair behind the radial face (contact clearance)
D.f0 = mod(D.phiMin + D.delta + cD + D.eps, D.p);
const psiH = D.f0 - D.eps + 5 * D.p;
D.holdPin = [D.pinR * Math.cos(psiH - D.pinBack), D.pinR * Math.sin(psiH - D.pinBack)];
export function profile(alpha, theta) { const u = mod(alpha - theta - D.f0, D.p); return D.rT - (D.rT - D.rR) * u / D.p; }
export function faceNear(alpha, theta) { const u = mod(alpha - theta - D.f0, D.p); return u < D.p / 2 ? -u : D.p - u; } // signed angle to nearest face
const okAt = (pin, theta, rho) => { const tp = tipFor(pin, D.Lp, rho); return rho >= profile(Math.atan2(tp[1], tp[0]), theta) - 1e-9; };
const mk = (pin, rho) => { const tip = tipFor(pin, D.Lp, rho); return { pin, tip, rho, ang: Math.atan2(tip[1] - pin[1], tip[0] - pin[0]), tipAng: Math.atan2(tip[1], tip[0]) }; };
// spring-loaded continuation: from previous radius, fall inward until material, or get lifted out by material
function follow(pin, theta, rho0) {
  const ok = (r) => okAt(pin, theta, r), st = 0.008;
  let a, b;
  if (ok(rho0)) { if (ok(D.rR)) { let r = rho0; while (r > D.rR && ok(r - st)) r -= st; if (r - st <= D.rR && ok(D.rR)) return D.rR; a = r - st; b = r; } else { let r = rho0; while (ok(r - st)) r -= st; a = r - st; b = r; } }
  else { let r = rho0; while (!ok(r + st) && r < D.rT + 1) r += st; a = r; b = r + st; }
  for (let k = 0; k < 28; k++) { const m = (a + b) / 2; if (ok(m)) b = m; else a = m; }
  return b;
}
function minimal(pin, theta) { let a = D.rR, b = D.rT + 0.5; if (okAt(pin, theta, a)) return a; for (let i = 1; i <= 400; i++) { const r = D.rR + (b - D.rR) * i / 400; if (okAt(pin, theta, r)) { b = r; a = r - (D.rT + 0.5 - D.rR) / 400; break; } }
  for (let k = 0; k < 28; k++) { const m = (a + b) / 2; if (okAt(pin, theta, m)) b = m; else a = m; } return b; }
export function solvePawl(pin, theta, rho0) { return mk(pin, rho0 == null ? minimal(pin, theta) : follow(pin, theta, rho0)); }
const TN = 1440, TAB = [];
function raw(t) {
  const a = crankAngle(t), lk = leverAt(a), phi = lk.phi, working = t < D.tWork;
  const push = working ? Math.min(D.p, Math.max(0, phi - D.phiMin - D.delta)) : D.p;
  return { a, lk, phi, working, push, pin: [D.pinR * Math.cos(phi), D.pinR * Math.sin(phi)] };
}
{ let rd = null, rh = null;
  for (let i = 0; i <= TN; i++) { const q = raw(i / TN); rd = rd == null ? minimal(q.pin, q.push) : follow(q.pin, q.push, rd); rh = rh == null ? minimal(D.holdPin, q.push) : follow(D.holdPin, q.push, rh); TAB.push([rd, rh]); } }
export function pose(t, n) {
  t = mod(t, 1);
  const q = raw(t), phi = q.phi, push = q.push, working = q.working, theta = n * D.p + push;
  const i = Math.floor(t * TN), base = TAB[i];
  const drive = solvePawl(q.pin, theta, base[0]), hold = solvePawl(D.holdPin, theta, base[1]);
  const engaged = working && push > 0 && phi - D.phiMin > D.delta;
  return { t, n, a: q.a, crankPin: q.lk.C, leverPin: q.lk.B, phi, theta, push, working, engaged, drive, hold,
    teeth: n + push / D.p };
}
// Curved pawl: inner (wheel-facing) edge bows outward from the chord tip->pin so the body clears tooth tips.
D.bow = 8;
export function pawlEdge(w, k = 16) {
  const dx = w.pin[0] - w.tip[0], dy = w.pin[1] - w.tip[1], L = Math.hypot(dx, dy);
  let nx = -dy / L, ny = dx / L; const mx = (w.tip[0] + w.pin[0]) / 2, my = (w.tip[1] + w.pin[1]) / 2;
  if (nx * mx + ny * my < 0) { nx = -nx; ny = -ny; }
  return Array.from({ length: k + 1 }, (_, i) => { const f = i / k, b = D.bow * Math.sin(Math.PI * Math.min(1, f * 1.25)) * (f < 0.8 ? 1 : 1);
    return [w.tip[0] + dx * f + nx * b, w.tip[1] + dy * f + ny * b]; });
}
// Attempt to back-drive the wheel CW: limited by holding-pawl face (wheel can only fall back to last caught notch)
export function reverseAttempt(t, n) {
  const ps = pose(t, n), caught = Math.floor(ps.theta / D.p + 1e-9) * D.p;
  return { requested: -D.p, allowed: caught - ps.theta, blocked: true };
}
export function init() { return { t: 0, n: 0, playing: false, msg: '' }; }
export function advance(s, dt) {
  let t = s.t + dt / D.period, n = s.n;
  while (t >= 1) { t -= 1; n += 1; }
  return { ...s, t, n };
}
export function stepCycle(s) { return { ...s, t: 0, n: s.n + 1, playing: false }; }

