import { D, pose, profile, faceNear, reverseAttempt, init, advance, pawlEdge } from './model.mjs';
const S = 720;
export function verify() {
  const out = [], add = (name, passed, detail = '') => out.push({ name, passed: !!passed, detail });
  const ps = Array.from({ length: S }, (_, i) => pose(i / S, 3));
  add('lever swing exceeds one tooth pitch', D.delta > 0.01 && D.delta < D.p * 0.5, `swing ${(D.swing * 180 / Math.PI).toFixed(2)}°`);
  let clo = 0; for (const q of ps) { clo = Math.max(clo, Math.abs(Math.hypot(...q.leverPin) - D.R), Math.abs(Math.hypot(q.leverPin[0] - q.crankPin[0], q.leverPin[1] - q.crankPin[1]) - D.L)); }
  add('four-bar closes at every sampled crank angle', clo < 1e-6, `err ${clo.toExponential(2)}`);
  let mono = true, back = 0; for (let i = 1; i < S; i++) { const d = ps[i].theta - ps[i - 1].theta; if (d < -1e-12) { mono = false; back = i / S; } }
  add('wheel never rotates backwards over a cycle', mono, `at t=${back}`);
  const ret = ps.filter((q) => !q.working);
  add('wheel stationary during whole return stroke', ret.length > 10 && ret.every((q) => Math.abs(q.theta - 4 * D.p) < 1e-12));
  const end = pose(0.99999, 3), nxt = pose(0, 4);
  add('one cycle advances exactly one tooth', Math.abs(nxt.theta - 3 * D.p - D.p) < 1e-12 && Math.abs(end.theta - nxt.theta) < 1e-9);
  let pen = 0, at = 0; for (const q of ps) for (const w of [q.drive, q.hold]) { const g = w.rho - profile(w.tipAng, q.theta); if (g < pen) { pen = g; at = q.t; } }
  add('pawl tips never penetrate tooth profile', pen > -0.02, `min gap ${pen.toFixed(4)} at t=${at}`);
  const push = ps.filter((q) => q.engaged); let fe = 0;
  for (const q of push) fe = Math.max(fe, Math.abs(faceNear(q.drive.tipAng, q.theta)) * q.drive.rho, Math.abs(q.drive.rho - D.rR));
  add('drive pawl seated on radial face throughout push', push.length > 20 && fe < 0.3, `max offset ${fe.toFixed(3)} mm`);
  const r0 = pose(0, 5); const hf = Math.abs(faceNear(r0.hold.tipAng, r0.theta)) * r0.hold.rho;
  add('holding pawl seated against face at rest', hf < 0.3 && Math.abs(r0.hold.rho - D.rR) < 0.3, `offset ${hf.toFixed(3)}`);
  add('reverse rotation blocked at rest', Math.abs(reverseAttempt(0, 2).allowed) < 1e-9 && reverseAttempt(0, 2).blocked);
  let chord = 9; for (const q of ps.filter((_, i) => i % 6 === 0)) for (const w of [q.drive, q.hold]) for (const [x, y] of pawlEdge(w, 20).slice(2)) {
    const r = Math.hypot(x, y);
    if (r < D.rT + 1) chord = Math.min(chord, r - profile(Math.atan2(y, x), q.theta)); }
  add('pawl bodies clear the teeth behind the tip', chord > -0.05, `min ${chord.toFixed(3)}`);
  let lk = 0; for (const q of ps) for (const w of [q.drive, q.hold]) lk = Math.max(lk, Math.abs(Math.hypot(w.tip[0] - w.pin[0], w.tip[1] - w.pin[1]) - D.Lp));
  add('pawl lengths rigid', lk < 1e-6);
  let s = init(); s = advance(s, D.period * 0.5); const n1 = s.n; s = advance(s, D.period * 0.6);
  add('playback crosses cycle boundary into next count', n1 === 0 && s.n === 1 && Math.abs(s.t - 0.1) < 1e-9);
  const maxRho = Math.max(...ret.map((q) => q.drive.rho));
  add('drive pawl rides over a tooth tip on return', maxRho > D.rT - 0.5, `max rho ${maxRho.toFixed(2)}`);
  const iMax = ret.findIndex((q) => q.drive.rho === maxRho), later = Math.min(...ret.slice(iMax).map((q) => q.drive.rho));
  add('drive pawl clicks down into next tooth space on return', iMax >= 0 && later < D.rR + 3, `after tip ${later.toFixed(2)} mm`);
  add('lever plane clears wheel and pawls axially', D.zL[0] - D.zW[1] >= 2 && D.zC[0] > D.zL[1]);
  const hEnd = pose(0.99999, 3).hold, hStart = pose(0, 4).hold;
  add('holding pawl drops and is seated before the cycle ends', Math.abs(hEnd.rho - hStart.rho) < 0.05 && Math.abs(hEnd.rho - D.rR) < 0.3, `rho end ${hEnd.rho.toFixed(3)}`);
  const dEnd = pose(0.99999, 3).drive, dStart = pose(0, 4).drive;
  add('drive pawl state continuous across cycle boundary', Math.abs(dEnd.rho - dStart.rho) < 0.05, `${dEnd.rho.toFixed(3)} vs ${dStart.rho.toFixed(3)}`);
  const wk = ps.filter((q) => q.working); let inc = true; for (let i = 1; i < wk.length; i++) if (wk[i].phi < wk[i - 1].phi - 1e-9) inc = false;
  add('working stroke = lever rising from min to max', inc && Math.abs(ps[0].phi - D.phiMin) < 1e-3 && D.tWork > 0.3 && D.tWork < 0.7, `tWork ${D.tWork.toFixed(3)}`);
  return out;
}

