import { D, pose, init, advance, stepCycle, reverseAttempt, faceNear, profile } from './model.mjs';
import { camera, drawScene, inset } from './geometry.mjs';
const deg = (r) => (r * 180 / Math.PI).toFixed(1);
export function mount(root, env) {
  let s = init(), raf = 0, last = 0, inspect = false, which = 'drive', reduced = env.reducedMotion, visible = true;
  root.innerHTML = `<div class="rt">
  <div class="rt-bar" role="group" aria-label="Controls">
    <button id="play" type="button">Play</button><button id="step" type="button">Advance one cycle</button>
    <button id="reset" type="button">Reset</button><button id="reverse" type="button">Try to turn backwards</button>
    <button id="inspect" type="button" aria-pressed="false">Inspect contact</button>
  </div>
  <label class="rt-range">Crank phase <input id="phase" type="range" min="0" max="1000" value="0"><output id="phaseOut">0%</output></label>
  <p id="status" class="rt-status" aria-live="polite"></p>
  <div class="rt-stage"><svg id="art" class="iso" viewBox="0 0 600 470" role="img" aria-label="Ratchet wheel with drive pawl on an oscillating lever, holding pawl, crank and coupler on a base plate"></svg>
   <div id="insetBox" class="rt-insetbox" hidden><p class="rt-cap">Optional close-up · top view, 7× <button id="which" type="button">Show holding pawl</button></p><svg id="insetSvg" viewBox="0 0 220 160"></svg><p id="contact" class="rt-small"></p></div></div>
  <ul class="rt-legend"><li><i class="sw ok"></i>Allowed: wheel turns counter‑clockwise (green arrow)</li><li><i class="sw no"></i>Blocked: clockwise rotation (red arrow, ✕) — holding pawl catches a radial face</li><li><i class="sw ac"></i>Ratchet wheel · <i class="sw md"></i>pawls, lever, crank, coupler</li></ul>
  <details class="rt-det"><summary>How it is built</summary><p>A crank on its own bearing post drives a coupler; the coupler swings the lever about the wheel shaft (a crank‑rocker four‑bar, swing ${deg(D.swing)}°, tooth pitch ${deg(D.p)}°). The drive pawl hangs below the lever in the wheel plane; the holding pawl pivots on a post fixed to the base. Both are spring‑loaded inward. Rigid, frictionless kinematics only — not a load rating.</p></details>
  <p id="msg" class="rt-msg" aria-live="polite"></p></div>`;
  const $ = (id) => root.querySelector('#' + id);
  const P = camera(600, 470);
  function draw() {
    const ps = pose(s.t, s.n);
    $('art').innerHTML = drawScene(ps, P, { inspect });
    $('play').textContent = s.playing ? 'Pause' : 'Play';
    $('phase').value = String(Math.round(s.t * 1000)); $('phaseOut').textContent = Math.round(s.t * 100) + '%';
    const stroke = ps.working ? (ps.engaged ? 'Working stroke — drive pawl pushes, wheel advancing' : 'Working stroke — pawl taking up slack') : 'Return stroke — wheel held still, drive pawl clicks over a tooth';
    $('status').textContent = `${stroke} · Teeth advanced: ${ps.teeth.toFixed(2)} · Wheel ${deg(ps.theta)}° · Lever ${deg(ps.phi - D.phiMin)}°`;
    if (inspect) {
      const w = which === 'hold' ? ps.hold : ps.drive;
      $('insetSvg').innerHTML = inset(ps, which);
      const face = Math.abs(faceNear(w.tipAng, ps.theta)) * w.rho, gap = w.rho - profile(w.tipAng, ps.theta);
      const touching = face < 0.3 && Math.abs(w.rho - D.rR) < 0.3;
      $('contact').textContent = `${which === 'hold' ? 'Holding' : 'Drive'} pawl tip: ${touching ? 'seated on radial face' : 'riding on tooth flank'} · face offset ${face.toFixed(2)} mm · penetration ${Math.max(0, -gap).toFixed(2)} mm`;
    }
  }
  function frame(now) {
    raf = 0; if (!s.playing || !visible) return;
    const dt = Math.min(0.1, (now - last) / 1000); last = now;
    s = advance(s, reduced ? dt * 0.5 : dt); draw(); raf = requestAnimationFrame(frame);
  }
  function start() { if (raf) cancelAnimationFrame(raf); last = performance.now(); raf = requestAnimationFrame(frame); }
  const stop = () => { if (raf) cancelAnimationFrame(raf); raf = 0; };
  const msg = (t) => { $('msg').textContent = t; };
  $('play').onclick = () => { s = { ...s, playing: !s.playing }; s.playing ? start() : stop(); msg(s.playing ? 'Playing' : 'Paused'); draw(); };
  $('step').onclick = () => { stop(); s = stepCycle(s); msg(`Advanced one full cycle: wheel moved one tooth (${deg(D.p)}°)`); draw(); };
